"""Portable review/delivery copies. No artwork is raster-edited by this tool."""
from pathlib import Path
import json,shutil,hashlib,html
ROOT=Path(__file__).resolve().parents[1];LIB=ROOT/'Biblioteca de Arte';REL='Personagens Jogaveis/Orc V1';OUT=LIB/REL;OUT.mkdir(parents=True,exist_ok=True)
if (ROOT/'characters/orc-v1/source/equipment-current.json').exists() and json.loads((ROOT/'characters/orc-v1/source/equipment-current.json').read_text(encoding='utf-8'))['revision']!='weapons-v2':
 raise SystemExit('V2 rejected and superseded. Use tools/build-main-orc-rescue-review.py; no armed Idle/Walk in current review.')
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
files=[]

# Self-contained rejected v1 review, same directory depth so its relative links stay valid.
history=LIB/'Historico de Entregas/Orc V1 - Armas v1'
if not history.exists():
 shutil.copytree(ROOT/'experiments/orc-v1-weapons-v2/preserved-v1/portable-review',history)
 p=history/'index.html';p.write_text(p.read_text(encoding='utf-8').replace('<main>','<main><p><strong>HISTÓRICO V1 REJEITADO PELO CRIADOR.</strong> Preservado para comparação. <a href="../../Personagens Jogaveis/Orc V1/index.html">Ver revisão candidata v2</a></p>',1),encoding='utf-8')
def copy(source,dest):
 p=OUT/dest;p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/source,p);files.append({'file':dest,'source':source,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()});return dest
concept=copy('characters/orc-v1/concepts/concept-selected.png','Personagem/Conceito.png')
conceptMaster=copy('characters/orc-v1/source/aseprite/concept-selected.aseprite','Personagem/Conceito.aseprite')
idle=read(ROOT/'characters/orc-v1/source/studies/Idle/clip.json')
data=[{'title':'Orc V1 · Idle padrão','state':'Idle','width':128,'height':128,'loop':True,'frames':[{'png':copy(f['png'],f'Personagem/Idle/{i:02d}.png'),'durationMs':f['durationMs']} for i,f in enumerate(idle['frames'])]}]
idleMaster=copy(idle['master'],'Personagem/Idle.aseprite')
rows=[]
for wid in ['recruit-sword','militia-axe']:
 weapon=read(ROOT/f'assets/weapons/{wid}/weapon.json');folder='Armas/'+weapon['name'];sprite=copy(weapon['sprite'],folder+'/'+weapon['name']+'.png');master=copy(weapon['master'],folder+'/'+weapon['name']+'.aseprite')
 copy(f'assets/weapons/{wid}/weapon.json',folder+'/weapon.json')
 sections=[f'<section><h3>Arma separada · uma mão</h3><div class="weapon-stage"><img width="96" height="96" class="weapon" src="{sprite}" alt="{weapon["name"]}"></div><p>{html.escape(weapon["description"])}</p><p><a href="{sprite}">PNG</a> · <a href="{master}">Aseprite</a></p></section>']
 for state,title in [('Idle','Repouso armado · padrão fixo 2,2 s'),('Walk','Caminhada · loop completo'),('Attack','Golpe · repetido para revisão')]:
  source=f'characters/orc-v1/source/equipment-v2/{wid}/{state}';clip=read(ROOT/source/'clip.json');frames=[]
  for i,f in enumerate(clip['frames']):
   png=copy(f['png'],folder+'/'+state+f'/Quadros/{i:02d}.png');frames.append({'png':png,'durationMs':f['durationMs']})
   for name,item in f['layers'].items():copy(item['png'],folder+'/'+state+f'/Camadas/{name}/{i:02d}.png')
  cm=copy(clip['master'],folder+'/'+state+'/'+state+'.aseprite');sheet=copy(source+'/native-strip.png',folder+'/'+state+'/native-strip.png')
  entry={'title':weapon['name']+' · '+state,'state':state,'width':256,'height':256,'loop':clip['loop'],'frames':frames,'master':cm,'canonicalClip':source+'/clip.json'};i=len(data);data.append(entry)
  local={**clip,'frames':[{'png':f'Quadros/{n:02d}.png','durationMs':f['durationMs'],'sha256':clip['frames'][n]['sha256'],'rightGrip':clip['frames'][n]['rightGrip'],'layers':{name:'Camadas/'+name+f'/{n:02d}.png' for name in clip['frames'][n]['layers']}} for n,f in enumerate(frames)],'master':state+'.aseprite','canonicalClip':source+'/clip.json'}
  (OUT/folder/state/'clip.json').write_text(json.dumps(local,ensure_ascii=False,indent=2),encoding='utf-8')
  sections.append(f'<section><h3>{title}</h3><div class="stage"><canvas id="anim-{i}" width="256" height="256" aria-label="{weapon["name"]} {state}"></canvas></div><p class="frame" id="frame-{i}"></p><p><a href="{cm}">Aseprite com camadas</a> · <a href="{sheet}">Folha completa PNG</a> · <a href="{folder}/{state}/clip.json">Quadros e encaixes</a></p></section>')
 rows.append(f'<article><h2>{weapon["name"]}</h2><div class="weapon-row">'+''.join(sections)+'</div></article>')
STYLE='''*{box-sizing:border-box}body{margin:0;background:#142126;color:#e6ece8;font:15px/1.5 system-ui}main{max-width:2100px;margin:auto;padding:24px}a,h3{color:#dfc18b}p{color:#b8ccc6}h1{font-size:36px}article{border:1px solid #4d666d;border-radius:8px;padding:18px;background:#22353c;margin:20px 0;min-width:0}.hero{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.hero img,.hero canvas{width:256px;height:256px;image-rendering:pixelated}.weapon-row{display:grid;grid-template-columns:180px repeat(3,minmax(0,1fr));gap:20px}.weapon-row section{min-width:0}.stage{height:536px;overflow:auto;display:flex;justify-content:center;align-items:center;background:repeating-conic-gradient(#283b42 0 25%,#375159 0 50%) 0/20px 20px}.stage canvas{width:512px;height:512px;image-rendering:pixelated;flex-shrink:0}.weapon-stage{height:290px;display:flex;align-items:center;justify-content:center;background:#192a30}.weapon{width:256px;height:256px;image-rendering:pixelated}.toolbar{position:sticky;top:0;display:flex;gap:12px;flex-wrap:wrap;padding:12px;background:#15242a;z-index:2;border-bottom:1px solid #4d666d}button,select{font:inherit;padding:8px;background:#344c54;color:white;border:1px solid #6c868d;border-radius:4px}.frame{font-size:13px}@media(max-width:1800px){.weapon-row{grid-template-columns:1fr}.weapon-stage{justify-content:start}}@media(max-width:600px){main{padding:12px}.stage{height:280px}.stage canvas{width:256px;height:256px}}'''
SCRIPT=r'''const views=data.map(()=>({n:0,time:0,pause:0}));const cache=new Map;let ready=false,playing=true,last=0,speed=1;function asset(p){if(!cache.has(p))cache.set(p,new Promise((ok,no)=>{const im=new Image;im.onload=()=>ok(im);im.onerror=()=>no(Error(p));im.src=p}));return cache.get(p)}async function draw(i){const c=data[i],f=c.frames[views[i].n],im=await asset(f.png),ctx=document.getElementById('anim-'+i).getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(im,0,0);const note=document.getElementById('frame-'+i);if(note)note.textContent=(views[i].n+1)+'/'+c.frames.length+' quadros · '+f.durationMs+' ms · ciclo '+c.frames.reduce((a,f)=>a+f.durationMs,0)+' ms'}Promise.all(data.flatMap(c=>c.frames.map(f=>asset(f.png)))).then(()=>Promise.all(data.map((_,i)=>draw(i)))).then(()=>{ready=true;document.body.dataset.ready='true'});document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pausar':'Reproduzir'};document.getElementById('reset').onclick=()=>views.forEach((v,i)=>{v.n=0;v.time=0;v.pause=0;draw(i)});document.getElementById('step').onclick=()=>{playing=false;document.getElementById('play').textContent='Reproduzir';views.forEach((v,i)=>{v.n=(v.n+1)%data[i].frames.length;draw(i)})};document.getElementById('speed').onchange=e=>speed=Number(e.target.value);document.getElementById('zoom').onchange=e=>{const z=Number(e.target.value);document.querySelectorAll('.stage canvas').forEach(c=>c.style.width=c.style.height=(c.width*z)+'px');document.querySelectorAll('.stage').forEach(c=>c.style.height=(256*z+24)+'px')};function tick(t){const dt=last?Math.min(100,t-last)*speed:0;last=t;if(ready&&playing)views.forEach((v,i)=>{const c=data[i];if(v.pause>0){v.pause-=dt;return}v.time+=dt;if(v.time>=c.frames[v.n].durationMs){v.time-=c.frames[v.n].durationMs;v.n=(v.n+1)%c.frames.length;if(v.n===0&&c.state==='Attack')v.pause=350;draw(i)}});requestAnimationFrame(tick)}requestAnimationFrame(tick);'''
page=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orc V1 · espada e machado</title><style>{STYLE}</style><main><h1>Orc V1 · revisão das armas v2</h1><p>Verde Warcraft selecionado pelo criador como primeiro jogável para futura integração. Revisão candidata: espada maior, acabamento das armas, pegada com dedos sobre o cabo, Idle armado e uma família compartilhada de golpe. Vista três quartos. Aguarda sua avaliação.</p><p><a href="../../index.html">Biblioteca de Arte</a> · <a href="../../Orcs Atuais/05 - Infante de Ferro/index.html">Infante original preservado</a> · <a href="LEIA-ME.md">Arquivos e documentação</a></p><div class="toolbar"><button id="play">Pausar</button><button id="reset">Reiniciar</button><button id="step">Avançar quadro</button><label>Velocidade <select id="speed"><option value="1">1×</option><option value="0.5">0,5×</option><option value="0.25">0,25×</option></select></label><label>Zoom equipado <select id="zoom"><option value="1">1× nativo</option><option value="2" selected>2×</option></select></label></div><article class="hero"><section><h3>Orc V1 · conceito</h3><img src="{concept}" alt="Orc V1 Verde Warcraft"></section><section><h3>Idle · padrão fixo 2,2 s</h3><canvas id="anim-0" width="128" height="128"></canvas><p class="frame" id="frame-0"></p></section><section><h2>Seleção preservada</h2><p>Espada e machado são assets independentes.<br>A caminhada armada foi solicitada pelo criador.<br>Linguagem visual do jogo; armas independentes de raça ou classe.<br>Mesmo corpo, pegada e tempos para itens compatíveis.</p><p><a href="{conceptMaster}">Mestre do conceito</a> · <a href="{idleMaster}">Mestre do Idle</a></p></section></article>{''.join(rows)}<p>Prévia local: corpo, arma e dedos têm camadas registradas nos mestres e nos PNGs. O golpe se repete nesta página para revisão; sua ação não é um loop automático no jogo. A integração Unity e as demais vistas ainda são etapas posteriores.</p></main><script>const data={json.dumps(data,ensure_ascii=False)};{SCRIPT}</script></html>'''
page=page.replace('.weapon{width:256px;height:256px;','.weapon{width:192px;height:192px;')
page=page.replace('<div class="toolbar">','<p><a href="../../Historico de Entregas/Orc V1 - Armas v1/index.html">Comparar com v1 rejeitada</a> · <a href="Rig Reutilizavel/rig.json">Rig compartilhado</a></p><div class="toolbar">',1)
(OUT/'index.html').write_text(page,encoding='utf-8')
rig=read(ROOT/'experiments/orc-v1-weapons-v2/binding-rig.json');localRig={**rig,'states':{}}
for state,c in rig['states'].items():
 frames=[]
 for n,f in enumerate(c['frames']):
  item={k:v for k,v in f.items() if k not in ['body','palmBack','fingersFront']}
  for name in ['body','palmBack','fingersFront']:
   target=f'Rig Reutilizavel/{state}/{name}/{n:02d}.png';copy(f[name],target);item[name]=f'{state}/{name}/{n:02d}.png'
  frames.append(item)
 master=copy(c['master'],f'Rig Reutilizavel/{state}/body.aseprite');localRig['states'][state]={**c,'master':f'{state}/body.aseprite','frames':frames}
(OUT/'Rig Reutilizavel/rig.json').write_text(json.dumps(localRig,ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'catalogo.json').write_text(json.dumps({'date':'2026-10-25','character':'orc-v1','players':data,'files':files,'artisticApproval':'PENDING_CREATOR_WEAPONS','unityIntegrated':False},ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'LEIA-ME.md').write_text((ROOT/'docs/ORC_V1_WEAPONS_V2.md').read_text(encoding='utf-8'),encoding='utf-8')
for src,dst in [('docs/WEAPON_ART_STANDARD.md','PADRAO-DE-ARMAS.md'),('docs/ORC_V1_WEAPONS_V2.md','DOCUMENTACAO-ORC-V1.md')]:
 (OUT/dst).write_text((ROOT/src).read_text(encoding='utf-8'),encoding='utf-8')
p=ROOT/'docs/ART_LIBRARY_COMPARISONS.json';registry=read(p);registry=[c for c in registry if c['id'] not in ['orc-v1-weapons-v1','orc-v1-weapons-v2']];registry.insert(0,{'id':'orc-v1-weapons-v2','title':'Orc V1 · armas v2, Idle, caminhada e golpe','path':REL+'/index.html','builder':'tools/build-orc-v1-weapons-v2-review.py'});p.write_text(json.dumps(registry,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'page':str(OUT/'index.html'),'players':len(data),'equippedClips':6,'separateWeapons':2,'copiedFiles':len(files)},ensure_ascii=False))
